 1	#include <stdint.h>
 2	
 3	/* Địa chỉ thanh ghi từ CMSIS-STM32F469XX-H dòng 1118, 1139, 1209, 1215 */
 4	#define PERIPH_BASE           (0x40000000UL)
 5	#define AHB1PERIPH_BASE       (PERIPH_BASE + 0x00020000UL)
 6	
 7	#define RCC_BASE              (AHB1PERIPH_BASE + 0x3800UL)
 8	#define RCC_AHB1ENR           (*(volatile uint32_t *)(RCC_BASE + 0x30UL))
 9	#define RCC_AHB1ENR_GPIOGEN   (1UL << 6)
10	
11	#define GPIOG_BASE            (AHB1PERIPH_BASE + 0x1800UL)
12	#define GPIOG_MODER           (*(volatile uint32_t *)(GPIOG_BASE + 0x00UL))
13	#define GPIOG_ODR             (*(volatile uint32_t *)(GPIOG_BASE + 0x14UL))
14	#define GPIOG_BSRR            (*(volatile uint32_t *)(GPIOG_BASE + 0x18UL))
15	
16	/* LED1 (Green) nối vào chân PG6 (tài liệu BSP-STM32469I-DISCO-H dòng 131, 145) */
17	#define LED1_PIN              (6U)
18	
19	static void delay_cycles(volatile uint32_t count) {
20	    while (count--) {
21	        __asm__ volatile ("nop");
22	    }
23	}
24	
25	int main(void) {
26	    /* 1. Bật xung nhịp cho cổng GPIOG */
27	    RCC_AHB1ENR |= RCC_AHB1ENR_GPIOGEN;
28	
29	    /* 2. Cấu hình PG6 thành General Purpose Output mode (MODER[13:12] = 01b) */
30	    GPIOG_MODER &= ~(3UL << (LED1_PIN * 2));
31	    GPIOG_MODER |=  (1UL << (LED1_PIN * 2));
32	
33	    /* 3. Vòng lặp chính: đảo trạng thái đèn LED1 với chu kỳ ~0.5s */
34	    while (1) {
35	        /* Bật LED1 */
36	        GPIOG_BSRR = (1UL << LED1_PIN);
37	        delay_cycles(1000000);
38	
39	        /* Tắt LED1 */
40	        GPIOG_BSRR = (1UL << (LED1_PIN + 16));
41	        delay_cycles(1000000);
42	    }
43	
44	    return 0;
45	}

