#include <stdint.h>

/*
 * Địa chỉ ngoại vi từ tài liệu CMSIS-STM32F469XX-H (dòng 1201–1240)
 */
#define PERIPH_BASE           (0x40000000UL)
#define AHB1PERIPH_BASE       (PERIPH_BASE + 0x00020000UL)

#define RCC_BASE              (AHB1PERIPH_BASE + 0x3800UL)
#define RCC_AHB1ENR           (*(volatile uint32_t *)(RCC_BASE + 0x30UL))

#define GPIOA_BASE            (AHB1PERIPH_BASE + 0x0000UL)
#define GPIOD_BASE            (AHB1PERIPH_BASE + 0x0C00UL)
#define GPIOG_BASE            (AHB1PERIPH_BASE + 0x1800UL)
#define GPIOK_BASE            (AHB1PERIPH_BASE + 0x2800UL)

/* Các thanh ghi GPIO cần dùng */
#define GPIOA_MODER           (*(volatile uint32_t *)(GPIOA_BASE + 0x00UL))
#define GPIOA_PUPDR           (*(volatile uint32_t *)(GPIOA_BASE + 0x0CUL))
#define GPIOA_IDR             (*(volatile uint32_t *)(GPIOA_BASE + 0x10UL))

#define GPIOD_MODER           (*(volatile uint32_t *)(GPIOD_BASE + 0x00UL))
#define GPIOD_BSRR            (*(volatile uint32_t *)(GPIOD_BASE + 0x18UL))

#define GPIOG_MODER           (*(volatile uint32_t *)(GPIOG_BASE + 0x00UL))
#define GPIOG_BSRR            (*(volatile uint32_t *)(GPIOG_BASE + 0x18UL))

#define GPIOK_MODER           (*(volatile uint32_t *)(GPIOK_BASE + 0x00UL))
#define GPIOK_BSRR            (*(volatile uint32_t *)(GPIOK_BASE + 0x18UL))

/*
 * Bit kích hoạt xung nhịp RCC AHB1 từ CMSIS-STM32F469XX-H (dòng 14001–14040)
 */
#define RCC_AHB1ENR_GPIOAEN   (1UL << 0)
#define RCC_AHB1ENR_GPIODEN   (1UL << 3)
#define RCC_AHB1ENR_GPIOGEN   (1UL << 6)
#define RCC_AHB1ENR_GPIOKEN   (1UL << 10)

/*
 * Thông số chân 4 đèn LED & Nút bấm từ Fact dự án:
 * - LED1 (Green):  PG6  (Fact f-8008940bff, BSP-STM32469I-DISCO-H dòng 121–160)
 * - LED2 (Orange): PD4  (Fact f-76c09827fe, BSP-STM32469I-DISCO-H dòng 121–160)
 * - LED3 (Red):    PD5  (Fact f-1357924537, BSP-STM32469I-DISCO-H dòng 121–160)
 * - LED4 (Blue):   PK3  (Fact f-61ed792479, BSP-STM32469I-DISCO-H dòng 121–160)
 * - USER_BUTTON:   PA0  (Fact f-e3204af421, f-0a0ea12b9e, BSP-STM32469I-DISCO-H dòng 161–200)
 *
 * Mức tích cực theo BSP-STM32469I-DISCO-C:
 * - LED: Active LOW (Fact f-2853301d9b bật = GPIO_PIN_RESET, Fact f-805562b793 tắt = GPIO_PIN_SET)
 * - Nút USER: Active HIGH (Fact f-be0a482f3c sườn lên GPIO_MODE_IT_RISING, bấm = 1, nhả = 0)
 */
#define LED1_PIN              (6U)  /* PG6 */
#define LED2_PIN              (4U)  /* PD4 */
#define LED3_PIN              (5U)  /* PD5 */
#define LED4_PIN              (3U)  /* PK3 */

#define BUTTON_PIN            (0U)  /* PA0 */

static void led_set(uint8_t led_index, uint8_t on) {
    /* on = 1 -> kéo xuống 0 (BSRR bit 16..31)
     * on = 0 -> kéo lên 1 (BSRR bit 0..15)
     */
    switch (led_index) {
        case 1: /* LED1: PG6 */
            GPIOG_BSRR = on ? (1UL << (LED1_PIN + 16)) : (1UL << LED1_PIN);
            break;
        case 2: /* LED2: PD4 */
            GPIOD_BSRR = on ? (1UL << (LED2_PIN + 16)) : (1UL << LED2_PIN);
            break;
        case 3: /* LED3: PD5 */
            GPIOD_BSRR = on ? (1UL << (LED3_PIN + 16)) : (1UL << LED3_PIN);
            break;
        case 4: /* LED4: PK3 */
            GPIOK_BSRR = on ? (1UL << (LED4_PIN + 16)) : (1UL << LED4_PIN);
            break;
        default:
            break;
    }
}

static void all_leds(uint8_t on) {
    led_set(1, on);
    led_set(2, on);
    led_set(3, on);
    led_set(4, on);
}

static uint8_t button_is_pressed(void) {
    /* PA0 đọc mức 1 là đang bấm (Active HIGH) */
    return (GPIOA_IDR & (1UL << BUTTON_PIN)) ? 1U : 0U;
}

static void delay_cycles(volatile uint32_t count) {
    while (count--) {
        __asm__ volatile ("nop");
    }
}

int main(void) {
    /* 1. Bật xung nhịp cho các cổng GPIOA, GPIOD, GPIOG, GPIOK */
    RCC_AHB1ENR |= (RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIODEN |
                    RCC_AHB1ENR_GPIOGEN | RCC_AHB1ENR_GPIOKEN);

    /* 2. Cấu hình các chân LED thành General Purpose Output mode (01b) */
    /* PG6 (LED1) */
    GPIOG_MODER &= ~(3UL << (LED1_PIN * 2));
    GPIOG_MODER |=  (1UL << (LED1_PIN * 2));

    /* PD4 (LED2), PD5 (LED3) */
    GPIOD_MODER &= ~((3UL << (LED2_PIN * 2)) | (3UL << (LED3_PIN * 2)));
    GPIOD_MODER |=  ((1UL << (LED2_PIN * 2)) | (1UL << (LED3_PIN * 2)));

    /* PK3 (LED4) */
    GPIOK_MODER &= ~(3UL << (LED4_PIN * 2));
    GPIOK_MODER |=  (1UL << (LED4_PIN * 2));

    /* 3. Cấu hình chân PA0 (USER BUTTON) thành Input mode (00b) */
    GPIOA_MODER &= ~(3UL << (BUTTON_PIN * 2));
    /* Theo BSP dòng 281-320: Pull = GPIO_NOPULL (00b) */
    GPIOA_PUPDR &= ~(3UL << (BUTTON_PIN * 2));

    /* Ban đầu tắt tất cả các đèn LED */
    all_leds(0);

    uint8_t step = 1;

    while (1) {
        if (button_is_pressed()) {
            /*
             * CHẾ ĐỘ 2: Nút đang BẤM
             * Phản ứng đổi rõ rệt: Cả 4 đèn LED chớp nháy đồng loạt cực nhanh (khác hẳn chạy tuần tự)
             */
            all_leds(1);
            delay_cycles(200000);
            all_leds(0);
            delay_cycles(200000);
        } else {
            /*
             * CHẾ ĐỘ 1: Nút đang NHẢ (bình thường)
             * Chạy tuần tự vòng quanh 4 đèn (Green -> Orange -> Red -> Blue)
             */
            led_set(1, (step == 1));
            led_set(2, (step == 2));
            led_set(3, (step == 3));
            led_set(4, (step == 4));

            delay_cycles(400000);

            step++;
            if (step > 4) {
                step = 1;
            }
        }
    }

    return 0;
}

